"""navera_lite/features.py — local features: gradients, the structure tensor, the Harris corner, OpenCV's ORB and
SIFT, repeatability, binary descriptors, and how matchable a picture is. Part of NAVERA Lite, the course's
teaching stack (mission 21). Written for the course; it is not NAVERA code.

Conventions: an image is a numpy array img[row, column] = img[y, x], (0, 0) at the TOP-LEFT, y grows DOWNWARDS
(mission 08). A point is (x, y) = (column, row), in pixels; a set of points is a float array of shape (N, 2).
A pixel's coordinates are those of its CENTRE: the top-left pixel is (0, 0). Gradients follow the course rule
of mission 08: the Sobel sums are divided by 8, so a ramp that climbs a grey levels per pixel gives exactly a.
A homography H (3 × 3) maps a point of picture 1 to picture 2 in homogeneous coordinates (mission 18).
"""
import cv2
import numpy as np

from navera_lite.image import to_gray


# ====================================================================== Harris, from the maths (session 1)

# from mission 21 — finished: read it, use it, do not change it
def gradients(gray):
    """The brightness gradient (gx, gy) of a grey picture, in grey levels per pixel, computed with OpenCV:
    gx > 0 where the picture gets brighter to the RIGHT, gy > 0 where it gets brighter DOWNWARDS. Same
    numbers as mission 08's navera_lite.image.sobel (3 × 3 Sobel, divided by 8, mirrored border), but fast.

    Input: a 2-D array (uint8 or float). Returns two float32 arrays of the picture's shape.
    Example: gradients(np.tile(np.arange(6, dtype=np.uint8) * 3, (5, 1)))[0][2]
             → array([0., 3., 3., 3., 3., 0.], dtype=float32)   (the ramp I = 3x; 0 at the mirrored borders)
    """
    g = np.asarray(gray, dtype=np.float32)
    gx = cv2.Sobel(g, cv2.CV_32F, 1, 0, ksize=3) / 8.0
    gy = cv2.Sobel(g, cv2.CV_32F, 0, 1, ksize=3) / 8.0
    return gx, gy


# from mission 21 — finished: read it, use it, do not change it
def structure_tensor(gx, gy, sigma=1.5):
    """The three entries of the structure tensor at every pixel: Sxx, Syy, Sxy = the products gx·gx, gy·gy
    and gx·gy, each averaged over a Gaussian window of standard deviation sigma pixels (lesson §2).

    Inputs: gx, gy (H, W) from gradients(); sigma > 0. Returns (sxx, syy, sxy), three float32 (H, W) arrays.
    Example: with gx = 20 and gy = 0 everywhere: structure_tensor(gx, gy) → sxx = 400, syy = 0, sxy = 0
             at every pixel (a vertical edge seen through any window)
    """
    gx = np.asarray(gx, dtype=np.float32)
    gy = np.asarray(gy, dtype=np.float32)
    sxx = cv2.GaussianBlur(gx * gx, (0, 0), sigma)
    syy = cv2.GaussianBlur(gy * gy, (0, 0), sigma)
    sxy = cv2.GaussianBlur(gx * gy, (0, 0), sigma)
    return sxx, syy, sxy


# from mission 21 — finished: read it, use it, do not change it
def eigen2(sxx, syy, sxy):
    """The two eigenvalues (l1, l2), l1 ≥ l2, of the symmetric 2 × 2 matrix [[sxx, sxy], [sxy, syy]]. Works on
    plain numbers and, element by element, on arrays of the same shape (one matrix per pixel).

    Returns two floats (numbers in) or two float arrays (arrays in).
    Example: eigen2(200.0, 200.0, 0.0) → (200.0, 200.0)      eigen2(400.0, 0.0, 0.0) → (400.0, 0.0)
             eigen2(5.0, 5.0, 3.0) → (8.0, 2.0)
    """
    half_tr = (np.asarray(sxx, dtype=np.float64) + syy) / 2.0
    root = np.sqrt(((np.asarray(sxx, dtype=np.float64) - syy) / 2.0) ** 2 + np.asarray(sxy, dtype=np.float64) ** 2)
    l1, l2 = half_tr + root, half_tr - root
    if np.ndim(l1) == 0:
        return float(l1), float(l2)
    return l1, l2


# from mission 21 — finished: read it, use it, do not change it
def harris(gray, k=0.04, sigma=1.5):
    """The Harris corner response R at every pixel (lesson §2): large and positive on corners, negative on
    edges, near 0 on flat ground. Uses your gradients() and structure_tensor() (window sigma).

    Input: a grey picture (H, W). Returns a float32 (H, W) array.
    Example: on a white square on a black background, R is largest near the 4 corners and negative along the
             middle of each side:  img = np.zeros((40, 40), np.uint8); img[10:30, 10:30] = 255
             harris(img)[10, 10] > 0 and harris(img)[20, 10] < 0  → True
    """
    sxx, syy, sxy = structure_tensor(*gradients(gray), sigma)
    return (sxx * syy - sxy * sxy - k * (sxx + syy) ** 2).astype(np.float32)


# from mission 21 — finished: read it, use it, do not change it
def harris_corners(gray, n=500, k=0.04, sigma=1.5, nms_radius=4, rel_threshold=0.01):
    """The n strongest Harris corners of a grey picture, as a float32 array (m, 2) of (x, y), strongest first
    (m ≤ n). A pixel is kept when (1) its R is the largest of its (2r+1) × (2r+1) neighbourhood (non-maximum
    suppression, r = nms_radius) and (2) R > rel_threshold × the largest R of the picture. Uses YOUR harris().

    Example: img = np.zeros((40, 40), np.uint8); img[10:30, 10:30] = 255
             harris_corners(img, 4) → the 4 corners of the square, about (10, 10), (29, 10), (10, 29), (29, 29)
    """
    # from mission 21 — finished: read it, use it, do not change it
    r = harris(gray, k, sigma)
    size = 2 * int(nms_radius) + 1
    peak = r == cv2.dilate(r, np.ones((size, size), np.uint8))          # dilate = the maximum around each pixel
    keep = peak & (r > rel_threshold * float(r.max()))
    ys, xs = np.nonzero(keep)
    order = np.argsort(-r[ys, xs], kind="stable")[:n]
    return np.column_stack([xs[order], ys[order]]).astype(np.float32).reshape(-1, 2)


# ====================================================================== OpenCV's detectors (given)

# from mission 21 — finished: read it, use it, do not change it
def detect(gray, method="orb", n=1000, contrast=None):
    """OpenCV's keypoints and descriptors of a picture (colour BGR or grey): returns (pts, des).
    pts: float32 (N, 2) of (x, y), N ≤ n, in OpenCV's order; des: one row per point — ORB: uint8 (N, 32), 256 bits;
    SIFT: float32 (N, 128) — or None when nothing is found (then pts has shape (0, 2)).
    method: "orb" or "sift" (any other name: ValueError). contrast: SIFT's contrastThreshold (OpenCV's default
    0.04; NAVERA uses 0.02 for pale map pictures); ignored by ORB.

    Example: detect(np.zeros((64, 64), np.uint8), "orb") → (array of shape (0, 2), None)   (nothing to find)
    """
    # from mission 21 — finished: read it, use it, do not change it
    g = to_gray(np.asarray(gray))
    if method == "orb":
        det = cv2.ORB_create(nfeatures=int(n))
    elif method == "sift":
        det = cv2.SIFT_create(nfeatures=int(n)) if contrast is None else \
            cv2.SIFT_create(nfeatures=int(n), contrastThreshold=float(contrast))
    else:
        raise ValueError(f"method must be 'orb' or 'sift', got {method!r}")
    kps, des = det.detectAndCompute(g, None)
    kps = list(kps)[:int(n)]
    if des is not None:
        des = des[:int(n)]
    pts = np.array([kp.pt for kp in kps], dtype=np.float32).reshape(-1, 2)
    return pts, (des if len(kps) else None)


# from mission 21 — finished: read it, use it, do not change it
def clahe(gray, clip=2.0, tiles=8):
    """Contrast Limited Adaptive Histogram Equalisation (lesson §6): stretches the contrast in tiles × tiles
    blocks, each stretch limited by clip. NAVERA's day vision applies clip 2.0 on 8 × 8 tiles. Returns uint8.

    Example: clahe(np.full((64, 64), 100, np.uint8)).std() → 0.0   (nothing to stretch on a uniform picture)
    """
    # from mission 21 — finished: read it, use it, do not change it
    return cv2.createCLAHE(clipLimit=float(clip), tileGridSize=(int(tiles), int(tiles))).apply(to_gray(gray))


# from mission 21 — finished: read it, use it, do not change it
def warp_points(H, pts):
    """Where the 3 × 3 homography H sends many points at once (mission 18's warp_point, for an (N, 2) array):
    each (x, y) becomes [x', y', w'] = H · [x, y, 1], then (x'/w', y'/w'). Returns float64 (N, 2).

    Example: warp_points(np.array([[2.0, 0, 5], [0, 2, 0], [0, 0, 1]]), [[1, 1], [0, 3]]) → [[7., 2.], [5., 6.]]
    """
    # from mission 21 — finished: read it, use it, do not change it
    p = np.asarray(pts, dtype=np.float64).reshape(-1, 2)
    hom = np.column_stack([p, np.ones(len(p))]) @ np.asarray(H, dtype=np.float64).T
    return hom[:, :2] / hom[:, 2:3]


# ====================================================================== measuring features

# from mission 21 — finished: read it, use it, do not change it
def repeatability(pts1, pts2, H, shape2, tol_px=3.0):
    """The share of picture 1's points that picture 2's detector finds again (lesson §4). Only the points of
    picture 1 whose image by H falls INSIDE picture 2 count (0 ≤ x ≤ w − 1 and 0 ≤ y ≤ h − 1); one of them is
    found again when a point of picture 2 lies within tol_px pixels (≤) of its image.

    Inputs: pts1 (N, 2), pts2 (M, 2) of (x, y); H (3 × 3) maps picture 1 to picture 2; shape2 = picture 2's
    .shape (h, w) or (h, w, 3). Returns a float from 0 to 1, and 0.0 when no point of picture 1 falls inside
    or picture 2 has no point.
    Example: repeatability([[1, 1], [5, 5], [50, 50]], [[3.0, 1.0], [9.0, 9.0]], np.eye(3), (20, 20))
             → 0.5   ((50, 50) is outside; (1, 1) has a point 2 px away; (5, 5) has none within 3 px)
    """
    h, w = shape2[:2]
    p = warp_points(H, pts1)
    inside = (p[:, 0] >= 0) & (p[:, 0] <= w - 1) & (p[:, 1] >= 0) & (p[:, 1] <= h - 1)
    p = p[inside]
    q = np.asarray(pts2, dtype=np.float64).reshape(-1, 2)
    if len(p) == 0 or len(q) == 0:
        return 0.0
    d = np.hypot(p[:, None, 0] - q[None, :, 0], p[:, None, 1] - q[None, :, 1]).min(axis=1)
    return float((d <= tol_px).mean())


# from mission 21 — finished: read it, use it, do not change it
def hamming(d1, d2):
    """The Hamming distance between two binary descriptors: the number of bits that differ (lesson §5).

    Inputs: two uint8 arrays of the same length (ORB: 32 bytes = 256 bits). Returns a Python int.
    Example: hamming(np.array([0b10110000], np.uint8), np.array([0b10010001], np.uint8)) → 2
    """
    a = np.asarray(d1, dtype=np.uint8)
    b = np.asarray(d2, dtype=np.uint8)
    return int(np.unpackbits(np.bitwise_xor(a, b)).sum())


# from mission 21 — finished: read it, use it, do not change it
def spread(pts, shape, grid=(4, 4), min_per_cell=3):
    """How well points cover a picture (lesson §6): cut it into grid = (columns, rows) equal cells and return the
    share of cells that hold at least min_per_cell points. A point on the right or bottom edge belongs to the
    last cell.

    Inputs: pts (N, 2) of (x, y), N may be 0; shape = the picture's .shape (h, w) or (h, w, 3).
    Returns a float from 0 to 1.
    Example: spread([[10, 10], [11, 12], [12, 11], [90, 90]], (100, 100), grid=(2, 2)) → 0.25
             (three points in the top-left cell; one alone in the bottom-right)
    """
    # from mission 21 — finished: read it, use it, do not change it
    h, w = shape[:2]
    cols, rows = int(grid[0]), int(grid[1])
    p = np.asarray(pts, dtype=np.float64).reshape(-1, 2)
    counts = np.zeros((rows, cols), int)
    for x, y in p:
        cx = min(cols - 1, max(0, int(x * cols / w)))
        cy = min(rows - 1, max(0, int(y * rows / h)))
        counts[cy, cx] += 1
    return float((counts >= min_per_cell).sum()) / (rows * cols)


# from mission 21 — finished: read it, use it, do not change it
def matchability(gray, n_enough=300):
    """Can this picture be matched on a map? Lesson §6's score from 0 (hopeless) to 1, with its reason, from at
    most 500 ORB keypoints (detect()) and spread() on the 4 × 4 grid. The reason is one of
    "too few features" (fewer than 10 keypoints: the score is 0.0), "features bunched" (spread below 0.25), "ok".

    Input: a grey (or BGR) picture. Returns (score, reason): a float from 0 to 1 and one of the three strings.
    Example: matchability(np.full((200, 200), 128, np.uint8)) → (0.0, "too few features")   (a uniform grey sea)
    """
    # from mission 21 — finished: read it, use it, do not change it
    pts, _ = detect(gray, "orb", 500)
    n = len(pts)
    if n < 10:
        return 0.0, "too few features"
    s = spread(pts, np.asarray(gray).shape)
    score = min(1.0, n / n_enough) * s
    return float(score), ("features bunched" if s < 0.25 else "ok")
